# ============================================================
# Scaling Law Model (EDITABLE)
# ============================================================

from scipy.optimize import differential_evolution as _de


def _fit_robust(resid_fn, x0, bounds=None, n_restarts=15, de_iter=100):
    """Global (DE) + local (least_squares) robust optimization."""
    x0 = np.asarray(x0, dtype=float)
    best_x, best_cost = x0.copy(), float('inf')
    try:
        r = np.nan_to_num(resid_fn(x0), nan=1e3, posinf=1e3, neginf=-1e3)
        best_cost = float(np.mean(r ** 2))
    except Exception:
        pass
    if bounds is not None:
        try:
            def obj(x):
                r = np.nan_to_num(resid_fn(x), nan=1e3, posinf=1e3, neginf=-1e3)
                return float(np.mean(r ** 2))
            res = _de(obj, bounds, maxiter=de_iter,
                       popsize=max(8, 5 * len(x0)),
                       mutation=(0.5, 1.5), recombination=0.9,
                       seed=42, tol=1e-9)
            if np.isfinite(res.fun) and res.fun < best_cost:
                best_cost, best_x = res.fun, res.x.copy()
        except Exception:
            pass
    rng = np.random.default_rng(42)
    lo = hi = ls_bounds = None
    if bounds is not None:
        lo = np.array([b[0] for b in bounds])
        hi = np.array([b[1] for b in bounds])
        ls_bounds = (lo, hi)
    else:
        ls_bounds = (-np.inf, np.inf)
    for i in range(n_restarts):
        if i == 0:
            u0 = best_x.copy()
        else:
            scale = 0.02 + 0.18 * (i / n_restarts)
            u0 = best_x + rng.normal(scale=scale, size=best_x.shape)
            if bounds is not None:
                u0 = np.clip(u0, lo, hi)
        try:
            res = least_squares(resid_fn, u0, method='trf',
                                loss='soft_l1', f_scale=0.05,
                                max_nfev=8000, bounds=ls_bounds)
            c = float(np.mean(res.fun ** 2))
            if np.isfinite(c) and c < best_cost:
                best_cost, best_x = c, res.x.copy()
        except Exception:
            pass
    return best_x


# ---- VOCAB: L = E + A*N^-a + B*V^-b + C*D^-c + F*N^-f1*V^-f2*D^-f3 ----

def _vocab_predict(X, p):
    n = np.clip(X[:, 0], 1.0, None)
    v = np.clip(X[:, 1], 1.0, None)
    d = np.clip(X[:, 2], 1.0, None)
    E, A, a, B, b, C, c, F, f1, f2, f3 = p
    return (E + A * n ** (-a) + B * v ** (-b) + C * d ** (-c)
            + F * n ** (-f1) * v ** (-f2) * d ** (-f3))


def _fit_vocab(X, y):
    yr = max(abs(float(y.max() - y.min())), 0.1)
    def unpack(u):
        return [u[0], np.exp(u[1]), np.exp(u[2]), np.exp(u[3]), np.exp(u[4]),
                np.exp(u[5]), np.exp(u[6]), np.exp(u[7]),
                np.exp(u[8]), np.exp(u[9]), np.exp(u[10])]
    def resid(u):
        return _vocab_predict(X, unpack(u)) - y
    u0 = [float(np.median(y)), np.log(yr), np.log(0.1),
          np.log(yr * 0.5), np.log(0.3), np.log(yr), np.log(0.3),
          np.log(yr * 0.1), np.log(0.1), np.log(0.1), np.log(0.1)]
    bounds = [(-20, 5), (-5, 5), (-5, 1), (-5, 5), (-5, 1),
              (-5, 5), (-5, 1), (-5, 5), (-5, 1), (-5, 1), (-5, 1)]
    best = _fit_robust(resid, u0, bounds, n_restarts=18, de_iter=130)
    return np.array(unpack(best))


# ---- LRBSZ: Chinchilla base + pos-def quadratic bowl in log space ----

def _lrbsz_predict(X, p):
    lr = np.clip(X[:, 0], 1e-12, None)
    bsz = np.clip(X[:, 1], 1.0, None)
    d = np.clip(X[:, 2], 1.0, None)
    n = np.clip(X[:, 3], 1.0, None)
    E, A, al, B, be, K1, K2, K3, c0, c1, c2, d0, d1 = p
    lr_s = c0 + c1 * np.log(n) + c2 * np.log(d)
    bsz_s = d0 + d1 * np.log(d)
    dlr = np.log(lr) - lr_s
    dbsz = np.log(bsz) - bsz_s
    base = E + A * d ** (-al) + B * n ** (-be)
    return base + K1 * dlr ** 2 + K2 * dbsz ** 2 + K3 * dlr * dbsz


def _fit_lrbsz(X, y):
    lr = np.clip(X[:, 0], 1e-12, None)
    bsz = np.clip(X[:, 1], 1.0, None)
    ymn, ymx = float(y.min()), float(y.max())
    yr = max(ymx - ymn, 0.1)
    llr = float(np.median(np.log(lr)))
    lbsz = float(np.median(np.log(bsz)))

    def unpack(u):
        K1 = np.exp(u[5])
        K2 = np.exp(u[6])
        # Ensure positive-definite quadratic form: |K3| < 2*sqrt(K1*K2)
        K3 = 2.0 * np.sqrt(K1 * K2) * np.tanh(u[7])
        return [u[0], np.exp(u[1]), np.exp(u[2]),
                np.exp(u[3]), np.exp(u[4]),
                K1, K2, K3,
                u[8], u[9], u[10], u[11], u[12]]

    def resid(u):
        pred = np.clip(_lrbsz_predict(X, unpack(u)), 1e-6, None)
        return np.log(pred) - np.log(np.clip(y, 1e-6, None))

    u0 = [max(ymn * 0.8, 0.5), np.log(yr), np.log(0.3),
          np.log(yr), np.log(0.1),
          np.log(0.05), np.log(0.01), 0.0,
          llr, -0.3, -0.2, lbsz, 0.3]
    bounds = [(0.0, 5.0), (-3, 8), (-4, 1), (-3, 8), (-4, 1),
              (-8, 4), (-8, 4), (-3, 3),
              (-30, 30), (-3, 3), (-3, 3), (-30, 30), (-3, 3)]
    best = _fit_robust(resid, u0, bounds, n_restarts=20, de_iter=150)
    return np.array(unpack(best))


# ---- DATACONSTRAINED: effective tokens + interaction term ----

def _dc_predict(X, p):
    u = np.clip(X[:, 0], 1.0, None)
    n = np.clip(X[:, 1], 1.0, None)
    d = np.clip(X[:, 2], 1.0, None)
    E, A, al, B, be, R, F, g, de = p
    ratio = np.clip(d / u, 0.0, 200.0)
    eff = 1.0 / (1.0 + ratio / max(R, 1e-3))
    d_eff = np.maximum(d * eff, 1.0)
    return E + A * n ** (-al) + B * d_eff ** (-be) + F * n ** (-g) * d_eff ** (-de)


def _fit_dc(X, y):
    ymn = float(y.min())
    yr = max(float(y.max() - y.min()), 0.1)
    def unpack(u):
        return [np.exp(u[0]), np.exp(u[1]), np.exp(u[2]),
                np.exp(u[3]), np.exp(u[4]), np.exp(u[5]),
                np.exp(u[6]), np.exp(u[7]), np.exp(u[8])]
    def resid(u):
        pred = np.clip(_dc_predict(X, unpack(u)), 1e-6, None)
        return np.log(pred) - np.log(np.clip(y, 1e-6, None))
    u0 = [np.log(max(ymn * 0.8, 0.1)), np.log(yr), np.log(0.35),
          np.log(yr), np.log(0.35), np.log(5.0),
          np.log(yr * 0.1), np.log(0.1), np.log(0.1)]
    bounds = [(-1, 3), (-3, 5), (-4, 1), (-3, 5), (-4, 1),
              (-2, 6), (-5, 5), (-4, 1), (-4, 1)]
    best = _fit_robust(resid, u0, bounds, n_restarts=18, de_iter=130)
    return np.array(unpack(best))


# ---- Dispatch ----

def _fit_params(bench, X, y):
    if bench == "sld-vocab":
        return _fit_vocab(X, y)
    if bench == "sld-lrbsz":
        return _fit_lrbsz(X, y)
    if bench == "sld-dataconstrained":
        return _fit_dc(X, y)
    raise ValueError(bench)


def _predict_params(bench, X, p):
    if bench == "sld-vocab":
        return _vocab_predict(X, p)
    if bench == "sld-lrbsz":
        return _lrbsz_predict(X, p)
    if bench == "sld-dataconstrained":
        return _dc_predict(X, p)
    raise ValueError(bench)


class ScalingLawModel:
    """Benchmark-specific symbolic laws with DE+LS robust fitting.

    vocab: additive power law + multiplicative N×V×D interaction
    lrbsz: Chinchilla base + positive-definite quadratic lr/bsz bowl
    dataconstrained: repeat-efficiency tokens + N×D_eff interaction
    """

    def __init__(self, benchmark_name, numeric_names=None, categorical_names=None):
        self.benchmark_name = benchmark_name
        self.numeric_names = list(numeric_names or [])
        self.categorical_names = list(categorical_names or [])
        self.group_params_ = {}
        self.default_params_ = None

    def fit(self, X_num, X_cat, y):
        X_num = np.asarray(X_num, dtype=float)
        y = np.asarray(y, dtype=float)
        labels = group_labels(X_cat)
        fitted = []
        for group in sorted(set(labels.tolist())):
            mask = labels == group
            params = _fit_params(self.benchmark_name, X_num[mask], y[mask])
            self.group_params_[group] = params
            fitted.append(params)
        self.default_params_ = np.median(np.stack(fitted, axis=0), axis=0)
        return self

    def predict(self, X_num, X_cat):
        X_num = np.asarray(X_num, dtype=float)
        labels = group_labels(X_cat)
        preds = np.zeros(len(labels), dtype=float)
        for group in sorted(set(labels.tolist())):
            mask = labels == group
            params = self.group_params_.get(group, self.default_params_)
            preds[mask] = _predict_params(self.benchmark_name,
                                          X_num[mask], params)
        return preds

# ============================================================
# Scaling Law Model (EDITABLE)
# ============================================================

def _slr(p, y):
    pc = np.clip(np.asarray(p, float), EPS, None)
    yc = np.clip(np.asarray(y, float), EPS, None)
    return np.log(pc) - np.log(yc)

def _lnr(p, y):
    return np.asarray(p, float) - np.asarray(y, float)

def _ls_fit(X, y, u0, unp, pred, nr=15, ul=True):
    u0 = np.asarray(u0, float); y = np.asarray(y, float)
    rng = np.random.default_rng(42)
    cs = [u0]
    for s in np.linspace(0.05, 0.5, max(nr - 1, 0)):
        cs.append(u0 + rng.normal(scale=s, size=u0.shape))
    bu, bs = u0, float("inf")
    for uc in cs:
        def res(u):
            try:
                pr = pred(X, unp(u))
                r = (_slr(pr, y) if ul else _lnr(pr, y))
                return np.nan_to_num(r, nan=1e3, posinf=1e3, neginf=-1e3)
            except Exception:
                return np.full_like(y, 1e3)
        try:
            out = least_squares(res, uc, method="trf", loss="soft_l1",
                                f_scale=0.05, max_nfev=8000)
            uo = out.x
        except Exception:
            uo = np.asarray(uc, float)
        pr = pred(X, unp(uo))
        s = float(np.mean((_slr(pr, y) if ul else _lnr(pr, y)) ** 2))
        if np.isfinite(s) and s < bs:
            bs, bu = s, uo
    return unp(bu), bu, bs

def _de_fit(X, y, unp, pred, bounds, u0=None, nr=15, ul=True, mi=250, ps=12):
    from scipy.optimize import differential_evolution as _de
    y = np.asarray(y, float)
    def obj(u):
        try:
            pr = pred(X, unp(u))
            r = (_slr(pr, y) if ul else _lnr(pr, y))
            return float(np.mean(r ** 2))
        except Exception:
            return 1e10
    params_de, u_de, s_de = None, None, float("inf")
    try:
        rd = _de(obj, bounds, seed=42, maxiter=mi, tol=1e-10,
                 polish=True, popsize=ps)
        params_de = unp(rd.x); u_de = rd.x; s_de = rd.fun
    except Exception:
        pass
    params_ls, u_ls, s_ls = None, None, float("inf")
    if u0 is not None:
        params_ls, u_ls, s_ls = _ls_fit(X, y, u0, unp, pred, nr=nr, ul=ul)
    params_ref = None
    if u_de is not None:
        def res(u):
            try:
                pr = pred(X, unp(u))
                r = (_slr(pr, y) if ul else _lnr(pr, y))
                return np.nan_to_num(r, nan=1e3, posinf=1e3, neginf=-1e3)
            except Exception:
                return np.full_like(y, 1e3)
        try:
            rl = least_squares(res, u_de, method="trf", loss="soft_l1",
                               f_scale=0.05, max_nfev=10000)
            params_ref = unp(rl.x)
        except Exception:
            pass
    cands = [(c, float(np.mean((_slr(pred(X, c), y) if ul else _lnr(pred(X, c), y)) ** 2)))
             for c in [params_ls, params_de, params_ref] if c is not None]
    cands = [(c, s) for c, s in cands if np.isfinite(s)]
    if not cands:
        return params_ls if params_ls is not None else params_de
    return min(cands, key=lambda x: x[1])[0]

# ---- VOCAB: L = E + A*N^-a + B*V^-b + C*D^-g ----
def _vp(X, p):
    n = np.clip(X[:, 0], 1.0, None)
    v = np.clip(X[:, 1], 1.0, None)
    d = np.clip(X[:, 2], 1.0, None)
    E, A, a, B, b, C, g = p
    return E + A * np.power(n, -a) + B * np.power(v, -b) + C * np.power(d, -g)

def _vu(u):
    return np.array([u[0], np.exp(u[1]), np.exp(u[2]), np.exp(u[3]),
                     np.exp(u[4]), np.exp(u[5]), np.exp(u[6])])

def _vf(X, y):
    y = np.asarray(y, float)
    init = np.array([float(np.median(y)),
                     np.log(max(abs(np.std(y)), 0.1)), np.log(0.1),
                     np.log(max(abs(np.std(y)), 0.1)), np.log(0.3),
                     np.log(max(abs(np.std(y)), 0.1)), np.log(0.3)])
    bounds = [(-20, 0), (-3, 7), (-5, 1.5), (-3, 7), (-5, 1.5),
              (-3, 7), (-5, 1.5)]
    return _de_fit(X, y, _vu, _vp, bounds, u0=init, nr=20, ul=False,
                   mi=350, ps=15)

# ---- LRBSZ: Chinchilla base + correlated (lr,bsz) quadratic bowl ----
def _lp(X, p):
    lr = np.clip(X[:, 0], 1e-12, None)
    bsz = np.clip(X[:, 1], 1.0, None)
    d = np.clip(X[:, 2], 1.0, None)
    n = np.clip(X[:, 3], 1.0, None)
    E, A, a, B, b, k1, a0, g, z, k2, b0, dd, eta, rho = p
    llo = a0 + g * np.log(n) + z * np.log(d)
    lbs = b0 + dd * np.log(n) + eta * np.log(d)
    dlr = np.log(lr) - llo
    dbs = np.log(bsz) - lbs
    cross = 2.0 * np.sqrt(np.maximum(k1, 0) * np.maximum(k2, 0)) * rho * dlr * dbs
    base = E + A * np.power(n, -a) + B * np.power(d, -b)
    return base + k1 * dlr ** 2 + k2 * dbs ** 2 + cross

def _lu(u):
    E = u[0]; A = np.exp(u[1]); a = np.exp(u[2])
    B = np.exp(u[3]); b = np.exp(u[4])
    k1 = np.exp(u[5]); a0 = u[6]; g = u[7]; z = u[8]
    k2 = np.exp(u[9]); b0 = u[10]; dd = u[11]; eta = u[12]
    rho = np.tanh(u[13])
    return np.array([E, A, a, B, b, k1, a0, g, z, k2, b0, dd, eta, rho])

def _lf(X, y):
    y = np.asarray(y, float)
    lr = np.clip(np.asarray(X[:, 0], float), 1e-12, None)
    bsz = np.clip(np.asarray(X[:, 1], float), 1.0, None)
    med_lr = float(np.median(lr)); med_bsz = float(np.median(bsz))
    init = np.array([
        float(max(y.min() * 0.9, 0.5)),
        np.log(max(np.std(y), 0.05)), np.log(0.06),
        np.log(max(np.std(y), 0.05)), np.log(0.15),
        np.log(0.05), np.log(med_lr), -0.3, 0.1,
        np.log(0.02), np.log(med_bsz), 0.0, 0.05, 0.0])
    bounds = [(-1, 5), (-5, 8), (-5, 1), (-5, 8), (-5, 1),
              (-8, 4), (-14, -1), (-2, 2), (-2, 2),
              (-8, 4), (0, 12), (-2, 2), (-2, 2), (-3, 3)]
    return _de_fit(X, y, _lu, _lp, bounds, u0=init, nr=25, ul=False,
                   mi=350, ps=15)

# ---- DATACONSTRAINED: Muennighoff effective tokens + efficiency ----
def _dp(X, p):
    u = np.clip(X[:, 0], 1.0, None)
    n = np.clip(X[:, 1], 1.0, None)
    d = np.clip(X[:, 2], 1.0, None)
    E, A, a, B, b, R = p
    ratio = np.clip(d / u, 0.0, 200.0)
    eff = 1.0 / (1.0 + ratio / np.maximum(R, 1e-3))
    d_eff = np.maximum(d * eff, 1.0)
    return E + A * np.power(n, -a) + B * np.power(d_eff, -b)

def _du(u):
    return np.array([np.exp(u[0]), np.exp(u[1]), np.exp(u[2]),
                     np.exp(u[3]), np.exp(u[4]), np.exp(u[5])])

def _df(X, y):
    y = np.asarray(y, float)
    init = np.array([np.log(max(y.min() * 0.9, 0.1)),
                     np.log(max(y.max() - y.min(), 0.1)), np.log(0.35),
                     np.log(max(y.max() - y.min(), 0.1)), np.log(0.35),
                     np.log(5.0)])
    bounds = [(-2, 4), (-5, 10), (-5, 2), (-5, 10), (-5, 2), (-2, 7)]
    return _de_fit(X, y, _du, _dp, bounds, u0=init, nr=20, ul=True,
                   mi=350, ps=15)

def _fp(bn, X, y):
    if bn == "sld-vocab": return _vf(X, y)
    if bn == "sld-lrbsz": return _lf(X, y)
    if bn == "sld-dataconstrained": return _df(X, y)
    raise ValueError(bn)

def _pp(bn, X, p):
    if bn == "sld-vocab": return _vp(X, p)
    if bn == "sld-lrbsz": return _lp(X, p)
    if bn == "sld-dataconstrained": return _dp(X, p)
    raise ValueError(bn)

class ScalingLawModel:
    """DE-optimized symbolic scaling laws with correlated penalty bowls."""

    def __init__(self, benchmark_name, numeric_names=None, categorical_names=None):
        self.benchmark_name = benchmark_name
        self.numeric_names = list(numeric_names or [])
        self.categorical_names = list(categorical_names or [])
        self.group_params_ = {}
        self.default_params_ = None

    def fit(self, X_num, X_cat, y):
        X_num = np.asarray(X_num, dtype=float)
        y = np.asarray(y, dtype=float)
        labels = group_labels(X_cat)
        fitted = []
        for group in sorted(set(labels.tolist())):
            mask = labels == group
            params = _fp(self.benchmark_name, X_num[mask], y[mask])
            self.group_params_[group] = params
            fitted.append(params)
        if fitted:
            self.default_params_ = np.median(np.stack(fitted, axis=0), axis=0)
        return self

    def predict(self, X_num, X_cat):
        X_num = np.asarray(X_num, dtype=float)
        labels = group_labels(X_cat)
        preds = np.zeros(len(labels), dtype=float)
        for group in sorted(set(labels.tolist())):
            mask = labels == group
            params = self.group_params_.get(group, self.default_params_)
            preds[mask] = _pp(self.benchmark_name, X_num[mask], params)
        return preds

