# Scaling Law Model (EDITABLE)
# ============================================================

def _poly_feat(X_log, power_list=None):
    """Degree-2 polynomial features from log inputs + optional power-law terms."""
    n, d = X_log.shape
    parts = [np.ones((n, 1)), X_log]
    for i in range(d):
        for j in range(i, d):
            parts.append((X_log[:, i] * X_log[:, j]).reshape(-1, 1))
    if power_list:
        for raw, exp in power_list:
            parts.append(np.power(raw, -exp).reshape(-1, 1))
    return np.concatenate(parts, axis=1)


def _ridge(X, y, alpha):
    d = X.shape[1]
    reg = alpha * np.eye(d)
    reg[0, 0] = 0.0
    return np.linalg.solve(X.T @ X + reg, X.T @ y)


def _pick_alpha(X, y, seed=42):
    alphas = [0.001, 0.01, 0.05, 0.1, 0.5, 1.0, 5.0, 10.0, 50.0, 100.0]
    n = len(y)
    rng = np.random.RandomState(seed)
    idx = rng.permutation(n)
    nv = max(int(0.15 * n), 2)
    vi, ti = idx[:nv], idx[nv:]
    best_a, best_s = 1.0, float('inf')
    for a in alphas:
        try:
            w = _ridge(X[ti], y[ti], a)
            s = float(np.mean((X[vi] @ w - y[vi]) ** 2))
            if np.isfinite(s) and s < best_s:
                best_s, best_a = s, a
        except Exception:
            pass
    return best_a


# --- Feature builders ---

def _feat_vocab(X):
    N = np.clip(X[:, 0], 1.0, None)
    V = np.clip(X[:, 1], 1.0, None)
    D = np.clip(X[:, 2], 1.0, None)
    Xl = np.column_stack([np.log(N), np.log(V), np.log(D)])
    pf = []
    for raw in [N, V, D]:
        for e in [0.05, 0.1, 0.15, 0.2, 0.3, 0.5]:
            pf.append((raw, e))
    return _poly_feat(Xl, pf)


def _feat_lrbsz(X):
    lr = np.clip(X[:, 0], 1e-10, None)
    bsz = np.clip(X[:, 1], 1.0, None)
    D = np.clip(X[:, 2], 1.0, None)
    N = np.clip(X[:, 3], 1.0, None)
    Xl = np.column_stack([np.log(lr), np.log(bsz), np.log(D), np.log(N)])
    pf = []
    for raw in [D, N]:
        for e in [0.05, 0.1, 0.15, 0.2, 0.3, 0.5]:
