def _pfeat(X, deg=2):
    """Polynomial features up to degree deg."""
    n, d = X.shape
    feats = [np.ones(n)]
    for i in range(d):
        feats.append(X[:, i])
    if deg >= 2:
        for i in range(d):
            for j in range(i, d):
                feats.append(X[:, i] * X[:, j])
    if deg >= 3:
        for i in range(d):
            for j in range(i, d):
                for k in range(j, d):
                    feats.append(X[:, i] * X[:, j] * X[:, k])
    return np.column_stack(feats)


def _ridge(X, y, alpha=1.0):
    d = X.shape[1]
    return np.linalg.solve(X.T @ X + alpha * np.eye(d), X.T @ y)


def _best_ridge(X, y):
    """Ridge with GCV selection."""
    alphas = np.logspace(-6, 6, 50)
    XtX = X.T @ X
    Xty = X.T @ y
    d, n = X.shape[1], X.shape[0]
    best_a, best_gcv = 1.0, float('inf')
    for a in alphas:
        try:
            M = np.linalg.solve(XtX + a * np.eye(d), X.T)
            w = M @ y
            mse = np.mean((y - X @ w) ** 2)
            h_mean = np.trace(X @ M) / n
            gcv = mse / max((1.0 - h_mean) ** 2, 1e-12)
            if gcv < best_gcv:
